//! The app's configuration (`app_config.rs`, since 0.24.0): `config/app.yaml` and its profiles,
//! what `fsp gen` writes from them, what it refuses, how a build picks its profile, and (with
//! `dart` on PATH) that the generated file compiles, picks the profile the define names and stops
//! a build whose define names none.

use std::fs;
use std::path::Path;

use crate::app_config::{
    self, Active, Change, Choice, Snapshot, check_profile, defined_in, emit, load, task_vars,
    with_define,
};
use crate::config::Config;
use crate::session::Session;

fn write(root: &Path, rel: &str, body: &str) {
    let p = root.join(rel);
    fs::create_dir_all(p.parent().unwrap()).unwrap();
    fs::write(p, body).unwrap();
}

/// A project with one page and the given files.
fn project(files: &[(&str, &str)]) -> tempfile::TempDir {
    let dir = tempfile::tempdir().unwrap();
    write(dir.path(), "pubspec.yaml", "name: demo\n");
    write(
        dir.path(),
        "lib/app/page.dart",
        "class HomePage extends StatelessWidget { const HomePage({super.key}); }",
    );
    for (rel, body) in files {
        write(dir.path(), rel, body);
    }
    dir
}

/// The diagnostics of `config/` for `files`, one line each (`✗ config/app.yaml:3  ...`).
fn diags(files: &[(&str, &str)]) -> Vec<String> {
    let dir = project(files);
    load(dir.path(), "lib/app.config.g.dart")
        .diags
        .0
        .iter()
        .map(ToString::to_string)
        .collect()
}

/// The generated file for `files`, which must have no errors.
fn generated(files: &[(&str, &str)]) -> String {
    let dir = project(files);
    let loaded = load(dir.path(), "lib/app.config.g.dart");
    assert!(!loaded.diags.has_errors(), "{:?}", loaded.diags);
    emit(loaded.config.as_ref().expect("a configuration"))
}

const BASE: &str = "\
# The app's name, on the splash.
app_name: Shop
api:
  # The API every call goes to.
  #
  # No trailing slash.
  base_url: https://api.example.com
  timeout_ms: 8000
  retry_ratio: 1
sentry_dsn: null
new_checkout: false
hosts: [api.example.com]
";

const DEV: &str = "\
api:
  base_url: http://localhost:8080
  retry_ratio: 0.5
new_checkout: true
hosts: [localhost, 10.0.2.2]
";

const STAGING: &str = "\
api:
  base_url: https://staging.example.com
sentry_dsn: https://abc@o1.ingest.sentry.io/2
";

fn shop() -> Vec<(&'static str, &'static str)> {
    vec![
        ("config/app.yaml", BASE),
        ("config/app.dev.yaml", DEV),
        ("config/app.staging.yaml", STAGING),
    ]
}

/// The whole file, for the configuration above: the header, the choice of the profile, the check
/// of `FSP_PROFILE`, and one constant per value, documented by the comment above its key. It is
/// what `dart format` writes (a constant on one line when it fits).
const SHOP_DART: &str = r"// GENERATED by fsp from config/: edit config/app.yaml, config/app.dev.yaml and config/app.staging.yaml, not this file.
// Every value here is compiled into the app, where anyone who has the app can read it: never a
// secret (docs/app-config.md).
// ignore_for_file: type=lint, unused_element

const String _requested = String.fromEnvironment('FSP_PROFILE');
const String _flavor = String.fromEnvironment('FLUTTER_APP_FLAVOR');
const bool _debug =
    !bool.fromEnvironment('dart.vm.product') &&
    !bool.fromEnvironment('dart.vm.profile');

/// The active profile: FSP_PROFILE (`fsp dev --profile`, `fsp build --profile`), else the
/// flavour (`--flavor`) when a profile has its name, else `dev` in a debug build when there is
/// a `dev` profile, else `default`.
const String _profile = bool.hasEnvironment('FSP_PROFILE')
    ? (_requested == '' ? 'default' : _requested)
    : _flavor == 'dev' || _flavor == 'staging'
    ? _flavor
    : _debug
    ? 'dev'
    : 'default';

/// A build whose FSP_PROFILE names no profile of config/ stops here, since dividing by zero is an
/// error in a constant. The profiles: `default`, `dev`, `staging`.
const int _fspProfileNamesNoFileOfConfig =
    1 ~/
    (_profile == 'default' || _profile == 'dev' || _profile == 'staging'
        ? 1
        : 0);

/// The values of config/app.yaml, with those of the active profile over them.
abstract final class AppConfig {
  /// The active profile: `default` (config/app.yaml alone), `dev` or `staging`.
  static const String profile = _profile;

  /// The app's name, on the splash.
  ///
  /// `app_name` in config/app.yaml.
  static const String appName = 'Shop';

  /// The API every call goes to.
  ///
  /// No trailing slash.
  ///
  /// `api.base_url` in config/app.yaml; set by `dev` and `staging`.
  static const String apiBaseUrl = _profile == 'dev'
      ? 'http://localhost:8080'
      : _profile == 'staging'
      ? 'https://staging.example.com'
      : 'https://api.example.com';

  /// `api.timeout_ms` in config/app.yaml.
  static const int apiTimeoutMs = 8000;

  /// `api.retry_ratio` in config/app.yaml; set by `dev`.
  static const double apiRetryRatio = _profile == 'dev' ? 0.5 : 1.0;

  /// `sentry_dsn` in config/app.yaml; set by `staging`.
  static const String? sentryDsn = _profile == 'staging'
      ? 'https://abc@o1.ingest.sentry.io/2'
      : null;

  /// `new_checkout` in config/app.yaml; set by `dev`.
  static const bool newCheckout = _profile == 'dev' ? true : false;

  /// `hosts` in config/app.yaml; set by `dev`.
  static const List<String> hosts = _profile == 'dev'
      ? ['localhost', '10.0.2.2']
      : ['api.example.com'];
}
";

#[test]
fn the_shop_configuration_makes_this_file() {
    assert_eq!(generated(&shop()), SHOP_DART);
}

#[test]
fn no_config_folder_is_no_configuration() {
    let dir = project(&[]);
    let loaded = load(dir.path(), "lib/app.config.g.dart");
    assert!(!loaded.on);
    assert!(loaded.config.is_none());
    assert!(loaded.diags.0.is_empty());
    // A folder of other files is not one either.
    let dir = project(&[
        ("config/README.md", "# ours\n"),
        ("config/ci.yaml", "a: 1\n"),
    ]);
    assert!(!load(dir.path(), "lib/app.config.g.dart").on);
}

#[test]
fn app_yaml_alone_has_only_the_default_profile() {
    let code = generated(&[("config/app.yaml", "title: Shop\n")]);
    assert!(code.contains(
        "const String _profile = bool.hasEnvironment('FSP_PROFILE')\n    ? (_requested == '' ? 'default' : _requested)\n    : 'default';\n"
    ));
    assert!(code.contains("1 ~/ (_profile == 'default' ? 1 : 0);"));
    assert!(code.contains("static const String title = 'Shop';"));
    assert!(!code.contains("_flavor"));
    assert!(!code.contains("_debug"));
}

#[test]
fn a_debug_build_has_dev_only_when_there_is_a_dev_profile() {
    let code = generated(&[
        ("config/app.yaml", "title: Shop\n"),
        ("config/app.staging.yaml", "title: Shop (staging)\n"),
    ]);
    assert!(code.contains("    : _flavor == 'staging'\n    ? _flavor\n    : 'default';\n"));
    assert!(!code.contains("_debug"));
}

#[test]
fn strings_are_escaped_and_ints_in_a_double_get_a_point() {
    let code = generated(&[(
        "config/app.yaml",
        "greeting: \"It's $5 \\\\ a\\nb\"\nratio: 2\nratios: [1, 0.5]\nbig: 9007199254740992\n",
    )]);
    assert!(code.contains(r"static const String greeting = 'It\'s \$5 \\ a\nb';"));
    assert!(code.contains("static const int ratio = 2;"));
    assert!(code.contains("static const List<double> ratios = [1.0, 0.5];"));
    assert!(code.contains("static const int big = 9007199254740992;"));
}

#[test]
fn a_profile_changes_only_keys_app_yaml_has() {
    assert_eq!(
        diags(&[
            ("config/app.yaml", "api:\n  base_url: https://a\n"),
            ("config/app.dev.yaml", "api:\n  base_ur: http://b\n"),
        ]),
        [
            "✗ config/app.dev.yaml:2  `api.base_ur` is not in config/app.yaml: a profile only changes values that config/app.yaml has (a typo?)"
        ]
    );
    assert_eq!(
        diags(&[
            ("config/app.yaml", "api:\n  base_url: https://a\n"),
            ("config/app.dev.yaml", "api: http://b\n"),
        ]),
        [
            "✗ config/app.dev.yaml:1  `api` is a map in config/app.yaml: config/app.dev.yaml can change the values in it, not replace it"
        ]
    );
    assert_eq!(
        diags(&[
            ("config/app.yaml", "api: https://a\n"),
            ("config/app.dev.yaml", "api:\n  base_url: http://b\n"),
        ]),
        ["✗ config/app.dev.yaml:1  `api` is a value in config/app.yaml, not a map"]
    );
}

#[test]
fn a_key_has_one_type_in_every_file() {
    assert_eq!(
        diags(&[
            ("config/app.yaml", "timeout: 30\n"),
            ("config/app.dev.yaml", "timeout: \"30s\"\n"),
        ]),
        [
            "✗ config/app.dev.yaml:1  `timeout` is a number in config/app.yaml and a string in config/app.dev.yaml: a key has one type in every file"
        ]
    );
    assert_eq!(
        diags(&[("config/app.yaml", "hosts: [a, 1]\n")]),
        ["✗ config/app.yaml:1  `hosts` holds a string and a number: a list holds one type"]
    );
    assert_eq!(
        diags(&[("config/app.yaml", "hosts: [[a]]\n")]),
        [
            "✗ config/app.yaml:1  `hosts` is a list of lists: a list holds strings, numbers or booleans"
        ]
    );
}

#[test]
fn null_and_empty_lists_take_their_type_from_another_file() {
    let code = generated(&[
        ("config/app.yaml", "dsn: null\nhosts: []\n"),
        ("config/app.prod.yaml", "dsn: https://x\nhosts: [a]\n"),
    ]);
    assert!(code.contains("static const String? dsn = _profile == 'prod'"));
    assert!(code.contains("static const List<String> hosts = _profile == 'prod' ? ['a'] : [];"));
    assert_eq!(
        diags(&[("config/app.yaml", "dsn: null\n")]),
        [
            "✗ config/app.yaml:1  `dsn` is null in config/app.yaml and in every profile, so fsp cannot tell its type: give it a value in one of them"
        ]
    );
    assert_eq!(
        diags(&[("config/app.yaml", "hosts: []\n")]),
        [
            "✗ config/app.yaml:1  `hosts` is an empty list in every file, so fsp cannot tell what it holds: give it a value in one of them"
        ]
    );
}

#[test]
fn profile_files_are_checked_by_their_names() {
    assert_eq!(
        diags(&[
            ("config/app.yaml", "a: 1\n"),
            ("config/app.release.yaml", "a: 2\n")
        ]),
        [
            "✗ config/app.release.yaml  `release` is a Flutter build mode (`flutter run --release`), not a profile: rename config/app.release.yaml"
        ]
    );
    assert_eq!(
        diags(&[
            ("config/app.yaml", "a: 1\n"),
            ("config/app.default.yaml", "a: 2\n")
        ]),
        [
            "✗ config/app.default.yaml  `default` is the name of config/app.yaml alone, not of a profile: rename config/app.default.yaml"
        ]
    );
    assert_eq!(
        diags(&[
            ("config/app.yaml", "a: 1\n"),
            ("config/app.a.b.yaml", "a: 2\n")
        ]),
        [
            "✗ config/app.a.b.yaml  `a.b` is not a profile name: use letters, digits, `_` and `-`, starting with a letter (config/app.<profile>.yaml)"
        ]
    );
    // With a config/app.yaml, a `.yml` file is an error: rename it.
    assert_eq!(
        diags(&[
            ("config/app.yaml", "a: 1\n"),
            ("config/app.dev.yml", "a: 2\n")
        ]),
        [
            "✗ config/app.dev.yml  fsp reads `.yaml` files in config/: rename config/app.dev.yml to config/app.dev.yaml"
        ]
    );
}

#[test]
fn without_app_yaml_the_feature_is_off_and_its_look_alikes_are_a_warning() {
    // An app on 0.23 that keeps config/app.yml, or a config/app.dev.yaml, for another tool: fsp
    // reads neither, says so once for each, and fails nothing (since 0.24.0).
    let ignored = |rel: &str| {
        format!(
            "! {rel}  {rel} is ignored: fsp reads only config/app.yaml and the config/app.<profile>.yaml beside it, and config/app.yaml is not there (docs/app-config.md)"
        )
    };
    for files in [
        vec![("config/app.yml", "a: 1\n")],
        vec![("config/app.dev.yaml", "a: 1\n")],
        vec![("config/app.dev.yml", "a: 1\n")],
        vec![("config/app.default.yaml", "a: 1\n")],
    ] {
        let dir = project(&files);
        let loaded = load(dir.path(), "lib/app.config.g.dart");
        assert!(!loaded.on, "{files:?}");
        assert!(loaded.config.is_none());
        assert!(!loaded.diags.has_errors(), "{files:?}: {:?}", loaded.diags);
        let said: Vec<String> = loaded.diags.0.iter().map(ToString::to_string).collect();
        assert_eq!(
            said,
            [ignored(&format!(
                "config/{}",
                files[0].0.rsplit('/').next().unwrap()
            ))]
        );
    }
    // One warning for each file, and the look-alikes only: another tool's files pass in silence.
    assert_eq!(
        diags(&[
            ("config/app.dev.yaml", "a: 1\n"),
            ("config/app.prod.yaml", "a: 1\n"),
            ("config/ci.yaml", "a: 1\n"),
            ("config/README.md", "# ours\n"),
        ]),
        [
            ignored("config/app.dev.yaml"),
            ignored("config/app.prod.yaml")
        ]
    );
    // They do not stop the routes: gen writes app.g.dart and no configuration, and succeeds.
    let dir = project(&[("config/app.yml", "a: 1\n")]);
    let cfg = Config::load(dir.path()).unwrap();
    let out = crate::gen_core(dir.path(), &cfg, true, &mut Session::default(), |_, _| {}).unwrap();
    assert_eq!(out.output, "lib/app.g.dart");
    assert!(dir.path().join("lib/app.g.dart").is_file());
    assert!(!dir.path().join("lib/app.config.g.dart").exists());
    // With a config/app.yaml beside them they are read, so a `.yml` is the error it was.
    assert!(
        load(
            project(&[("config/app.yaml", "a: 1\n"), ("config/app.yml", "a: 2\n")]).path(),
            "lib/app.config.g.dart"
        )
        .diags
        .has_errors()
    );
}

#[test]
fn keys_make_names_that_must_not_clash() {
    assert_eq!(
        diags(&[("config/app.yaml", "api_url: a\napi:\n  url: b\n")]),
        [
            "✗ config/app.yaml:3  `api.url` and `api_url` would both be the constant AppConfig.apiUrl: rename one"
        ]
    );
    assert_eq!(
        diags(&[("config/app.yaml", "default: a\n")]),
        [
            "✗ config/app.yaml:1  `default` would be the constant AppConfig.default, and `default` is a reserved word in Dart: rename the key"
        ]
    );
    assert_eq!(
        diags(&[("config/app.yaml", "profile: a\n")]),
        [
            "✗ config/app.yaml:1  `profile` would be the constant AppConfig.profile, which is the name of the active profile: rename the key"
        ]
    );
    assert_eq!(
        diags(&[("config/app.yaml", "2fa: true\n")]),
        [
            "✗ config/app.yaml:1  `2fa` is not a key fsp can name: a key is letters, digits, `_` and `-`, starting with a letter"
        ]
    );
    // A constant named like a type the class writes hides it for every other constant, and a name
    // every object has conflicts with the instance member: the generated file would not compile.
    for key in ["int", "bool", "double", "Int", "INT"] {
        let said = diags(&[("config/app.yaml", format!("{key}: 1\n").as_str())]);
        assert_eq!(said.len(), 1, "{key}: {said:?}");
        assert!(
            said[0].contains(
                "is a type that the class writes in its own declarations: rename the key"
            ),
            "{key}: {said:?}"
        );
    }
    assert_eq!(
        diags(&[("config/app.yaml", "int: 3\n")]),
        [
            "✗ config/app.yaml:1  `int` would be the constant AppConfig.int, and `int` is a type that the class writes in its own declarations: rename the key"
        ]
    );
    for (key, name) in [
        ("hash_code", "hashCode"),
        ("hashCode", "hashCode"),
        ("to_string", "toString"),
        ("runtime-type", "runtimeType"),
        ("no_such_method", "noSuchMethod"),
        ("HASH_CODE", "hashCode"),
    ] {
        assert_eq!(
            diags(&[("config/app.yaml", format!("{key}: 4\n").as_str())]),
            [format!(
                "✗ config/app.yaml:1  `{key}` would be the constant AppConfig.{name}, and `{name}` is a member that every Dart object has: rename the key"
            )]
        );
    }
    // Names of a group are only parts of a longer name: `api.int` is `apiInt`.
    let code = generated(&[("config/app.yaml", "api:\n  int: 1\n  hash_code: 2\n")]);
    assert!(code.contains("static const int apiInt = 1;"));
    assert!(code.contains("static const int apiHashCode = 2;"));
    // camelCase, snake_case and kebab-case keys all make a lowerCamelCase constant.
    let code = generated(&[(
        "config/app.yaml",
        "oidc:\n  clientId: a\n  redirect-uri: b\n  scope_list: [c]\n",
    )]);
    assert!(code.contains("static const String oidcClientId = 'a';"));
    assert!(code.contains("static const String oidcRedirectUri = 'b';"));
    assert!(code.contains("static const List<String> oidcScopeList = ['c'];"));
}

#[test]
fn every_spelling_of_a_key_is_one_name_for_the_constant_and_the_variable() {
    // The words of a key are read as the variable reads them (since 0.24.0), so an upper-case
    // key, as `--dart-define` names are, is not a mangled constant.
    for key in [
        "API_URL", "api_url", "apiURL", "api-url", "apiUrl", "Api_Url",
    ] {
        let code = generated(&[("config/app.yaml", format!("{key}: https://a\n").as_str())]);
        assert!(
            code.contains("static const String apiUrl = 'https://a';"),
            "{key}: {code}"
        );
        let config = load(
            project(&[("config/app.yaml", format!("{key}: https://a\n").as_str())]).path(),
            "lib/app.config.g.dart",
        )
        .config
        .unwrap();
        assert_eq!(
            task_vars(&config, "default"),
            [("FSP_CONFIG_API_URL".to_string(), "https://a".to_string())],
            "{key}"
        );
    }
    let code = generated(&[(
        "config/app.yaml",
        "URL: a\nredirectURI: b\noauth2:\n  CLIENT_ID: c\n  scope-list: [d]\nv2: e\n",
    )]);
    for expected in [
        "static const String url = 'a';",
        "static const String redirectUri = 'b';",
        "static const String oauth2ClientId = 'c';",
        "static const List<String> oauth2ScopeList = ['d'];",
        "static const String v2 = 'e';",
    ] {
        assert!(code.contains(expected), "{expected}: {code}");
    }
    // Two spellings of one key are one constant, and the constant says so first.
    assert_eq!(
        diags(&[("config/app.yaml", "API_URL: a\napiUrl: b\n")]),
        [
            "✗ config/app.yaml:2  `apiUrl` and `API_URL` would both be the constant AppConfig.apiUrl: rename one"
        ]
    );
}

#[test]
fn an_int_beyond_what_the_web_holds_is_an_error_the_smallest_included() {
    for value in [
        "9007199254740993",
        "-9007199254740993",
        "9223372036854775807",
        // `i64::MIN` has no absolute value in an i64: it panicked `fsp`.
        "-9223372036854775808",
        // Beyond an i64.
        "18446744073709551615",
    ] {
        assert_eq!(
            diags(&[("config/app.yaml", format!("x: {value}\n").as_str())]),
            [format!(
                "✗ config/app.yaml:1  `x` is {value}, more than an int holds exactly on the web (2^53): write it as a string"
            )],
            "{value}"
        );
    }
    // 2^53 itself is exact, either side of zero.
    let code = generated(&[(
        "config/app.yaml",
        "a: 9007199254740992\nb: -9007199254740992\n",
    )]);
    assert!(code.contains("static const int a = 9007199254740992;"));
    assert!(code.contains("static const int b = -9007199254740992;"));
}

#[test]
fn a_value_with_a_nul_character_is_an_error() {
    // Every value is a variable of the task's commands, and a NUL fails the spawn of each.
    let said = |yaml: &str| diags(&[("config/app.yaml", yaml)]);
    let expected = |key: &str, line: usize| {
        format!(
            "✗ config/app.yaml:{line}  `{key}` has a NUL character, which the environment of a command cannot hold (every value is a FSP_CONFIG_* variable of the task's commands): remove it"
        )
    };
    assert_eq!(said("a: \"x\\0y\"\n"), [expected("a", 1)]);
    // In a list, once.
    assert_eq!(said("a: [fine, \"x\\0y\"]\n"), [expected("a", 1)]);
    // In a profile.
    assert_eq!(
        diags(&[
            ("config/app.yaml", "a: x\n"),
            ("config/app.dev.yaml", "a: \"\\0\"\n")
        ]),
        [expected("a", 1).replace("config/app.yaml", "config/app.dev.yaml")]
    );
    // Other control characters are escaped in the Dart string and in the variable alike.
    assert!(said("a: \"x\\ty\"\n").is_empty());
}

#[test]
fn yaml_core_tags_are_read_as_yaml_says_and_a_tag_of_your_own_is_refused() {
    let code = generated(&[(
        "config/app.yaml",
        "a: !!str 123\nb: !!int \"5\"\nc: !!float 2\nd: !!bool \"true\"\n",
    )]);
    assert!(code.contains("static const String a = '123';"), "{code}");
    assert!(code.contains("static const int b = 5;"), "{code}");
    assert!(code.contains("static const double c = 2.0;"), "{code}");
    assert!(code.contains("static const bool d = true;"), "{code}");
    // Any other `!!` tag (`!!binary`, `!!timestamp`) is dropped by the parser: the text is the
    // value, not decoded. The docs say so.
    let code = generated(&[("config/app.yaml", "c: !!binary aGVsbG8=\n")]);
    assert!(
        code.contains("static const String c = 'aGVsbG8=';"),
        "{code}"
    );
    // A tag of your own, as in `!env HOME`, is an error.
    assert_eq!(
        diags(&[("config/app.yaml", "x: !env HOME\n")]),
        [
            "✗ config/app.yaml:1  `x` has the tag `!env`, which fsp does not read: write the value alone"
        ]
    );
}

#[test]
fn no_two_keys_are_one_variable_without_being_one_constant() {
    // The variable check of the task's commands is a second line behind the constants': both read
    // the words of a key the same way, so every message here is about a constant.
    let keys = [
        "api_url",
        "apiUrl",
        "API_URL",
        "api-url",
        "apiURL",
        "ApiUrl",
        "a1b",
        "a_1b",
        "a1_b",
        "A1B",
        "x2y",
        "x_2_y",
        "oauth2_id",
        "oauth2Id",
        "OAUTH2_ID",
        "a",
        "A",
        "ab",
        "aB",
        "a_b",
        "a-b",
    ];
    for a in keys {
        for b in keys {
            if a == b {
                continue;
            }
            for yaml in [
                format!("{a}: 1\n{b}: 2\n"),
                format!("{a}:\n  {b}: 1\n{a}_{b}: 2\n"),
            ] {
                for said in diags(&[("config/app.yaml", yaml.as_str())]) {
                    assert!(
                        !said.contains("would both be the variable"),
                        "{yaml:?}: {said}"
                    );
                }
            }
        }
    }
}

#[test]
fn a_file_that_is_no_map_or_no_yaml_is_an_error() {
    assert_eq!(
        diags(&[("config/app.yaml", "")]),
        [
            "✗ config/app.yaml  config/app.yaml has no values: write `key: value` lines, which `fsp gen` turns into the constants of AppConfig"
        ]
    );
    assert_eq!(
        diags(&[("config/app.yaml", "- a\n")]),
        [
            "✗ config/app.yaml  config/app.yaml must be a map of keys to values (`api_url: https://...`)"
        ]
    );
    let bad = diags(&[("config/app.yaml", "a: [1\n")]);
    assert_eq!(bad.len(), 1);
    assert!(bad[0].starts_with("✗ config/app.yaml:"), "{bad:?}");
    assert!(
        bad[0].contains("config/app.yaml is not YAML that fsp can read: "),
        "{bad:?}"
    );
    // An empty profile changes nothing, and is a profile.
    let code = generated(&[("config/app.yaml", "a: 1\n"), ("config/app.prod.yaml", "")]);
    assert!(code.contains("_flavor == 'prod'"));
}

#[test]
fn a_credential_is_an_error_and_a_secret_name_a_warning() {
    // Built at run time, so the fake key is no literal a secret scanner stops a push for.
    let stripe = format!("stripe:\n  key: sk_{}_aB3dE5gH7jK9mN1pQ2rS4tU6\n", "live");
    assert_eq!(
        diags(&[("config/app.yaml", stripe.as_str())]),
        [
            "✗ config/app.yaml:2  `stripe.key` in config/app.yaml looks like a Stripe secret key: every value in config/ is compiled into the app, where anyone who has the app can read it; keep the secret on a server and give the app only what it may show (docs/app-config.md, \"Secrets\")"
        ]
    );
    assert_eq!(
        diags(&[
            ("config/app.yaml", "db: https://example.com\n"),
            (
                "config/app.dev.yaml",
                "db: postgres://app:hunter2@localhost/app\n"
            ),
        ]),
        [
            "✗ config/app.dev.yaml:1  `db` in config/app.dev.yaml looks like a URL with a password in it: every value in config/ is compiled into the app, where anyone who has the app can read it; keep the secret on a server and give the app only what it may show (docs/app-config.md, \"Secrets\")"
        ]
    );
    assert_eq!(
        diags(&[(
            "config/app.yaml",
            "oauth:\n  client_secret: abc123\n  password_min: 8\n"
        )]),
        [
            "! config/app.yaml:2  `oauth.client_secret` in config/app.yaml is named like a secret: every value in config/ is compiled into the app, where anyone who has the app can read it; if it is a secret, keep it on a server (docs/app-config.md, \"Secrets\"), and if it is not, give it a name that says so"
        ]
    );
    // An empty value named like a secret says nothing: there is nothing in it yet.
    assert!(diags(&[("config/app.yaml", "client_secret: ''\n")]).is_empty());
    // A key that names where something is, and not the thing, is no secret by its name (since
    // 0.24.0): the advice "give it a name that says so" would be a name that already does.
    assert!(
        diags(&[(
            "config/app.yaml",
            "password_reset_url: https://example.com/reset\nforgot_password_url: https://example.com/forgot\nprivateKeyPath: assets/key.pem\ntoken_endpoint: https://auth.example.com/token\nsecret_link: https://example.com/s\nclient_secret_uri: https://example.com/s\n"
        )])
        .is_empty()
    );
    // A value that is refused by its shape is refused whatever the key is named.
    assert_eq!(
        diags(&[(
            "config/app.yaml",
            "password_reset_url: postgres://app:hunter2@db.example.com/app\n"
        )]),
        [
            "✗ config/app.yaml:1  `password_reset_url` in config/app.yaml looks like a URL with a password in it: every value in config/ is compiled into the app, where anyone who has the app can read it; keep the secret on a server and give the app only what it may show (docs/app-config.md, \"Secrets\")"
        ]
    );
    // A JWT is still a warning of its own under such a name.
    let token = format!(
        "eyJ{}.eyJ{}.{}",
        "hbGciOiJIUzI1NiJ9", "zdWIiOiI0MiJ9", "c2ln"
    );
    assert_eq!(
        diags(&[("config/app.yaml", format!("reset_url: {token}\n").as_str())]),
        [
            "! config/app.yaml:1  `reset_url` in config/app.yaml is a JWT: every value in config/ is compiled into the app, where anyone who has the app can read it; if the token grants access, keep it on a server (docs/app-config.md, \"Secrets\")"
        ]
    );
    // A warning does not stop the file.
    let dir = project(&[("config/app.yaml", "password: abc\n")]);
    assert!(load(dir.path(), "lib/app.config.g.dart").config.is_some());
}

#[test]
fn gen_writes_the_configuration_beside_the_output_and_fails_on_its_errors() {
    let dir = project(&[("config/app.yaml", "title: Shop\n")]);
    let cfg = Config::load(dir.path()).unwrap();
    let mut session = Session::default();
    let out = crate::gen_core(dir.path(), &cfg, true, &mut session, |_, _| {}).unwrap();
    assert_eq!(out.output, "lib/app.g.dart, lib/app.config.g.dart");
    // Written, and what the file holds now (since 0.24.1).
    let shop = Snapshot::of(&load(dir.path(), "lib/app.config.g.dart").config.unwrap());
    assert!(session.config_written);
    assert_eq!(session.config.as_ref(), Some(&shop));
    let written = fs::read_to_string(dir.path().join("lib/app.config.g.dart")).unwrap();
    assert!(written.contains("static const String title = 'Shop';"));
    // Unchanged: nothing written, and the pass says so, and what the file holds.
    let out = crate::gen_core(dir.path(), &cfg, true, &mut session, |_, _| {}).unwrap();
    assert!(!out.wrote);
    assert!(!session.config_written);
    assert_eq!(session.config.as_ref(), Some(&shop));
    // An error in config/ fails the pass but not the routes (since 0.24.0): `app.g.dart` does not
    // depend on config/, so a new page is written and the configuration alone stays as it was.
    write(
        dir.path(),
        "lib/app/about/page.dart",
        "class AboutPage extends StatelessWidget { const AboutPage({super.key}); }",
    );
    write(dir.path(), "config/app.dev.yaml", "titel: x\n");
    let routes_before = fs::read_to_string(dir.path().join("lib/app.g.dart")).unwrap();
    assert!(!routes_before.contains("AboutRoute"));
    // `check` writes nothing, and says only what is wrong.
    let err =
        crate::gen_core(dir.path(), &cfg, false, &mut Session::default(), |_, _| {}).unwrap_err();
    assert_eq!(format!("{err:#}"), "1 error(s) in config/");
    assert!(!err.is::<crate::FailedAfterWriting>());
    assert_eq!(
        fs::read_to_string(dir.path().join("lib/app.g.dart")).unwrap(),
        routes_before
    );
    let mut failed = Session::default();
    let err = crate::gen_core(dir.path(), &cfg, true, &mut failed, |_, _| {}).unwrap_err();
    assert_eq!(
        format!("{err:#}"),
        "1 error(s) in config/; lib/app.config.g.dart left unchanged; lib/app.g.dart is up to date"
    );
    assert!(err.is::<crate::FailedAfterWriting>());
    // What `fsp watch` and `fsp dev` read: the routes were written (so the app reloads), and the
    // configuration was not, nor read (so it does not restart for it).
    assert!(failed.wrote);
    assert!(!failed.config_written);
    assert_eq!(failed.config, None);
    let routes_after = fs::read_to_string(dir.path().join("lib/app.g.dart")).unwrap();
    assert!(routes_after.contains("AboutRoute"), "{routes_after}");
    assert_eq!(
        fs::read_to_string(dir.path().join("lib/app.config.g.dart")).unwrap(),
        written
    );
    // An error in the routes still stops everything, the configuration's included.
    write(
        dir.path(),
        "lib/app/page.dart",
        "class HomePage extends StatelessWidget { const HomePage({super.key}); }\nclass OtherPage extends StatelessWidget { const OtherPage({super.key}); }",
    );
    let err =
        crate::gen_core(dir.path(), &cfg, true, &mut Session::default(), |_, _| {}).unwrap_err();
    assert_eq!(
        format!("{err:#}"),
        "2 error(s); lib/app.g.dart and lib/app.config.g.dart left unchanged"
    );
    assert!(!err.is::<crate::FailedAfterWriting>());
    assert_eq!(
        fs::read_to_string(dir.path().join("lib/app.g.dart")).unwrap(),
        routes_after
    );
    // `output:` elsewhere moves it too.
    let dir = project(&[
        ("config/app.yaml", "title: Shop\n"),
        (
            "pubspec.yaml",
            "name: demo\nfespalier:\n  output: lib/router/routes.g.dart\n",
        ),
    ]);
    let cfg = Config::load(dir.path()).unwrap();
    assert_eq!(cfg.output_config(), "lib/router/routes.config.g.dart");
    crate::gen_core(dir.path(), &cfg, true, &mut Session::default(), |_, _| {}).unwrap();
    assert!(dir.path().join("lib/router/routes.config.g.dart").is_file());
}

/// What each pass leaves in the file of the configuration (since 0.24.1), as `fsp dev` reads it:
/// what changed from the configuration the last pass that read it left (`last`, which becomes this
/// pass's), whether the pass wrote the configuration, and whether it wrote the routes too.
fn written(
    dir: &Path,
    session: &mut Session,
    last: &mut Option<Snapshot>,
) -> (Option<Change>, bool, bool) {
    let cfg = Config::load(dir).unwrap();
    crate::gen_core(dir, &cfg, true, session, |_, _| {}).unwrap();
    let change = session
        .config
        .as_ref()
        .map(|now| app_config::change(last.as_ref(), now));
    if session.config.is_some() {
        last.clone_from(&session.config);
    }
    (change, session.config_written, session.routes_wrote)
}

fn changed(profiles: &[&str], profiles_changed: bool, changed: &[&str]) -> Option<Change> {
    Some(Change {
        profiles: profiles.iter().map(|p| (*p).to_string()).collect(),
        profiles_changed,
        changed: changed.iter().map(|p| (*p).to_string()).collect(),
    })
}

#[test]
fn a_configuration_says_which_profiles_it_changed() {
    let dir = project(&[
        (
            "config/app.yaml",
            "api_url: https://api.example.com\ntimeout: 5\n",
        ),
        ("config/app.dev.yaml", "api_url: http://localhost:8080\n"),
        (
            "config/app.staging.yaml",
            "api_url: https://staging.example.com\n",
        ),
    ]);
    let root = dir.path();
    let mut session = Session::default();
    let mut last = None;
    // The first pass writes the routes too, and there is nothing to compare with.
    let all = ["default", "dev", "staging"];
    let profiles = ["dev", "staging"];
    assert_eq!(
        written(root, &mut session, &mut last),
        (changed(&profiles, true, &all), true, true)
    );
    // A value only `dev` has: the configuration alone, and `dev` alone.
    write(
        root,
        "config/app.dev.yaml",
        "api_url: http://localhost:9090\n",
    );
    assert_eq!(
        written(root, &mut session, &mut last),
        (changed(&profiles, false, &["dev"]), true, false)
    );
    // A value of config/app.yaml that both profiles override: `default` alone.
    write(
        root,
        "config/app.yaml",
        "api_url: https://api2.example.com\ntimeout: 5\n",
    );
    assert_eq!(
        written(root, &mut session, &mut last).0,
        changed(&profiles, false, &["default"])
    );
    // One that none overrides, a type, a key: every profile.
    for base in [
        "api_url: https://api2.example.com\ntimeout: 6\n",
        "api_url: https://api2.example.com\ntimeout: 6.5\n",
        "api_url: https://api2.example.com\ntimeout: 6.5\nretries: 2\n",
    ] {
        write(root, "config/app.yaml", base);
        assert_eq!(
            written(root, &mut session, &mut last).0,
            changed(&profiles, false, &all),
            "{base}"
        );
    }
    // A null in one profile makes the constant nullable: its type changes for every profile.
    write(
        root,
        "config/app.staging.yaml",
        "api_url: https://staging.example.com\nretries: null\n",
    );
    assert_eq!(
        written(root, &mut session, &mut last).0,
        changed(&profiles, false, &all)
    );
    // A comment changes the file and no constant.
    write(
        root,
        "config/app.yaml",
        "# The API.\napi_url: https://api2.example.com\ntimeout: 6.5\nretries: 2\n",
    );
    assert_eq!(
        written(root, &mut session, &mut last),
        (changed(&profiles, false, &[]), true, false)
    );
    // A profile added: the profiles changed, and the new one's constants.
    write(root, "config/app.prod.yaml", "timeout: 9.5\n");
    let three = ["dev", "prod", "staging"];
    assert_eq!(
        written(root, &mut session, &mut last).0,
        changed(&three, true, &["prod"])
    );
    // An error in config/ leaves the file, and the pass does not say what it holds.
    write(
        root,
        "config/app.dev.yaml",
        "api_ur: http://localhost:9090\n",
    );
    let cfg = Config::load(root).unwrap();
    assert!(crate::gen_core(root, &cfg, true, &mut session, |_, _| {}).is_err());
    assert!(!session.config_written);
    assert_eq!(session.config, None);
    write(
        root,
        "config/app.dev.yaml",
        "api_url: http://localhost:9191\n",
    );
    assert_eq!(
        written(root, &mut session, &mut last).0,
        changed(&three, false, &["dev"])
    );
    // A new session (`fsp dev` starts one) that finds the file current writes nothing, and says
    // what it holds: what `fsp dev` compares with when flutter starts.
    let mut fresh = Session::default();
    assert_eq!(
        written(root, &mut fresh, &mut last),
        (changed(&three, false, &[]), false, false)
    );
    write(root, "config/app.prod.yaml", "timeout: 10.5\n");
    assert_eq!(
        written(root, &mut fresh, &mut last).0,
        changed(&three, false, &["prod"])
    );
    // Without config/app.yaml there is nothing to read, and the file is left as it is: the next
    // configuration is compared with what it holds.
    fs::remove_file(root.join("config/app.yaml")).unwrap();
    let cfg = Config::load(root).unwrap();
    let _ = crate::gen_core(root, &cfg, true, &mut fresh, |_, _| {});
    assert!(!fresh.config_written);
    assert_eq!(fresh.config, None);
    assert!(root.join("lib/app.config.g.dart").is_file());
    write(
        root,
        "config/app.yaml",
        "api_url: https://api2.example.com\ntimeout: 7.5\nretries: 2\n",
    );
    assert_eq!(
        written(root, &mut fresh, &mut last),
        (
            changed(&three, false, &["default", "dev", "staging"]),
            true,
            false
        )
    );
}

#[test]
fn a_profile_a_configuration_does_not_have_reads_the_values_of_default() {
    // A build reads `config/app.yaml`'s value for a key its profile does not set: a profile added
    // whose values are those changes no constant, and `profiles_changed` says it.
    let before = project(&[("config/app.yaml", "timeout: 5\n")]);
    let before = Snapshot::of(&load(before.path(), "lib/app.config.g.dart").config.unwrap());
    let after = project(&[
        ("config/app.yaml", "timeout: 5\n"),
        ("config/app.prod.yaml", "timeout: 5\n"),
    ]);
    let after = Snapshot::of(&load(after.path(), "lib/app.config.g.dart").config.unwrap());
    assert_eq!(after.profiles, ["prod"]);
    assert_eq!(
        Some(app_config::change(Some(&before), &after)),
        changed(&["prod"], true, &[])
    );
    // And one removed is not listed either.
    assert_eq!(
        Some(app_config::change(Some(&after), &before)),
        changed(&[], true, &[])
    );
}

#[test]
fn a_choice_chooses_again_with_other_profiles() {
    // What `fsp dev` keeps to follow a profile added or removed while the app runs (since 0.24.1).
    let profiles = |names: &[&str]| args(names);
    let debug = Choice::new(None, &[], None, true);
    assert_eq!(debug.active(&profiles(&["staging"])).name, "default");
    assert_eq!(debug.active(&profiles(&["dev", "staging"])).name, "dev");
    let flavor = Choice::new(None, &args(&["--flavor", "staging"]), None, true);
    assert_eq!(flavor.active(&profiles(&["dev"])).name, "dev");
    assert_eq!(
        flavor.active(&profiles(&["dev", "staging"])).name,
        "staging"
    );
    let named = Choice::new(Some("staging"), &[], None, true);
    assert_eq!(named.active(&profiles(&["dev", "staging"])).name, "staging");
    let release = Choice::new(None, &[], Some("prod"), false);
    assert_eq!(release.active(&profiles(&["dev"])).name, "default");
    assert_eq!(release.active(&profiles(&["dev", "prod"])).name, "prod");
}

#[test]
fn a_file_left_from_a_config_that_is_gone_is_a_warning() {
    let dir = project(&[(
        "lib/app.config.g.dart",
        "// GENERATED by fsp from config/: edit config/app.yaml, not this file.\n",
    )]);
    let loaded = load(dir.path(), "lib/app.config.g.dart");
    assert_eq!(
        loaded
            .diags
            .0
            .iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>(),
        [
            "! lib/app.config.g.dart  lib/app.config.g.dart was generated from config/app.yaml, which is gone: delete lib/app.config.g.dart, or put config/app.yaml back"
        ]
    );
    // A file of that name that fsp did not write is not ours to talk about.
    let dir = project(&[("lib/app.config.g.dart", "// mine\n")]);
    assert!(load(dir.path(), "lib/app.config.g.dart").diags.0.is_empty());
}

#[test]
fn a_configuration_that_output_moved_leaves_a_file_to_delete() {
    let old = "// GENERATED by fsp from config/: edit config/app.yaml, not this file.\n";
    let dir = project(&[
        ("config/app.yaml", "a: 1\n"),
        ("lib/app.config.g.dart", old),
    ]);
    let said = |output: &str| -> Vec<String> {
        load(dir.path(), output)
            .diags
            .0
            .iter()
            .map(ToString::to_string)
            .collect()
    };
    // `output:` moved the file: the old one keeps compiling in an import, with the old values.
    assert_eq!(
        said("lib/router/routes.config.g.dart"),
        [
            "! lib/app.config.g.dart  lib/app.config.g.dart was generated by fsp, and `output:` now puts the configuration in lib/router/routes.config.g.dart: an import of lib/app.config.g.dart still compiles, with the values it had, so delete it"
        ]
    );
    // The default place is where the file goes: nothing to say.
    assert!(said("lib/app.config.g.dart").is_empty());
    // A file there that fsp did not write is not ours to talk about.
    let mine = project(&[
        ("config/app.yaml", "a: 1\n"),
        ("lib/app.config.g.dart", "// mine\n"),
    ]);
    assert!(
        load(mine.path(), "lib/router/routes.config.g.dart")
            .diags
            .0
            .is_empty()
    );
    // `gen` shows it, and the new file is written.
    write(
        dir.path(),
        "pubspec.yaml",
        "name: demo\nfespalier:\n  output: lib/router/routes.g.dart\n",
    );
    let cfg = Config::load(dir.path()).unwrap();
    let mut shown = vec![];
    crate::gen_core(dir.path(), &cfg, true, &mut Session::default(), |_, d| {
        shown = d.0.iter().map(ToString::to_string).collect();
    })
    .unwrap();
    assert_eq!(shown.len(), 1, "{shown:?}");
    assert!(
        shown[0].starts_with("! lib/app.config.g.dart  "),
        "{shown:?}"
    );
    assert!(dir.path().join("lib/router/routes.config.g.dart").is_file());
}

fn args(words: &[&str]) -> Vec<String> {
    words.iter().map(|w| (*w).to_string()).collect()
}

#[test]
fn the_active_profile_is_the_define_then_the_flavour_then_the_build_mode() {
    let profiles = args(&["dev", "prod", "staging"]);
    let active = |explicit: Option<&str>, a: &[&str], default_flavor: Option<&str>, debug: bool| {
        Choice::new(explicit, &args(a), default_flavor, debug).active(&profiles)
    };
    let is = |name: &str, why: &'static str| Active {
        name: name.to_string(),
        why,
    };
    assert_eq!(
        active(Some("staging"), &["--flavor", "prod"], None, true),
        is("staging", "FSP_PROFILE")
    );
    assert_eq!(
        active(Some(""), &[], None, true),
        is("default", "FSP_PROFILE")
    );
    assert_eq!(
        active(None, &["--flavor", "prod"], None, true),
        is("prod", "the flavour")
    );
    assert_eq!(
        active(None, &["--flavor=prod"], None, false),
        is("prod", "the flavour")
    );
    assert_eq!(
        active(None, &[], Some("staging"), true),
        is("staging", "the flavour")
    );
    // A flavour that no profile is named after is not one.
    assert_eq!(
        active(None, &["--flavor", "free"], None, true),
        is("dev", "a debug build")
    );
    assert_eq!(active(None, &[], None, false), is("default", ""));
    let no_dev = Choice::new(None, &[], None, true).active(&args(&["prod"]));
    assert_eq!(no_dev, is("default", ""));
    assert_eq!(
        is("staging", "FSP_PROFILE").line(),
        "profile staging (FSP_PROFILE): config/app.staging.yaml over config/app.yaml"
    );
    assert_eq!(is("default", "").line(), "profile default: config/app.yaml");
    assert!(app_config::run_is_debug(&args(&["-d", "chrome"])));
    assert!(!app_config::run_is_debug(&args(&["--release"])));
    assert!(!app_config::run_is_debug(&args(&["--profile"])));
    assert!(!app_config::build_is_debug(&args(&["--release"])));
    assert!(app_config::build_is_debug(&args(&["--debug"])));
}

#[test]
fn fsp_reads_the_profile_of_its_own_flutter_run_and_not_of_a_file_or_a_command_of_the_pubspec() {
    // Its own `flutter run` with the arguments it reads (since 0.24.1).
    assert!(app_config::reads_build(true, &[]));
    assert!(app_config::reads_build(true, &args(&["-d", "chrome"])));
    assert!(app_config::reads_build(
        true,
        &args(&[
            "--flavor",
            "staging",
            "--dart-define=FSP_PROFILE=staging",
            "--release"
        ])
    ));
    // A `run:` of the pubspec's can say `--flavor` or a define where `fsp` does not look.
    assert!(!app_config::reads_build(false, &[]));
    assert!(!app_config::reads_build(
        false,
        &args(&["--flavor", "staging"])
    ));
    // A file of defines can set `FSP_PROFILE`, spelled either way.
    assert!(!app_config::reads_build(
        true,
        &args(&["--dart-define-from-file=env.json"])
    ));
    assert!(!app_config::reads_build(
        true,
        &args(&["--dart-define-from-file", "env.json"])
    ));
    // The line says what it assumes, and that the app restarts for every change.
    let dev = Active {
        name: "dev".into(),
        why: "a debug build",
    };
    assert_eq!(
        dev.line_unread(),
        "profile dev (a debug build): config/app.dev.yaml over config/app.yaml (a guess: fsp cannot read the profile of this run, so every change of config/ restarts the app)"
    );
    let default = Active {
        name: "default".into(),
        why: "",
    };
    assert_eq!(
        default.line_unread(),
        "profile default: config/app.yaml (a guess: fsp cannot read the profile of this run, so every change of config/ restarts the app)"
    );
}

#[test]
fn a_profile_flag_must_name_a_file_of_config() {
    let dir = project(&[
        ("config/app.yaml", "a: 1\n"),
        ("config/app.dev.yaml", "a: 2\n"),
    ]);
    assert!(check_profile(dir.path(), "dev").is_ok());
    assert!(check_profile(dir.path(), "default").is_ok());
    assert_eq!(
        format!("{:#}", check_profile(dir.path(), "stagng").unwrap_err()),
        "`--profile stagng`: there is no config/app.stagng.yaml; the profiles are default, dev"
    );
    assert_eq!(
        format!("{:#}", check_profile(dir.path(), "release").unwrap_err()),
        "`--profile release` names a profile of config/, and `release` is a Flutter build mode: pass that to flutter after `--` (`-- --release`)"
    );
    let none = project(&[]);
    assert_eq!(
        format!("{:#}", check_profile(none.path(), "dev").unwrap_err()),
        "`--profile dev`: this app has no config/app.yaml, so it has no profiles (docs/app-config.md)"
    );
}

#[test]
fn the_profile_goes_to_flutter_as_a_define_in_front_of_the_arguments() {
    assert_eq!(
        with_define(Some("staging"), &args(&["-d", "chrome"])).unwrap(),
        args(&["--dart-define=FSP_PROFILE=staging", "-d", "chrome"])
    );
    assert_eq!(
        with_define(None, &args(&["-d", "x"])).unwrap(),
        args(&["-d", "x"])
    );
    assert_eq!(
        format!(
            "{:#}",
            with_define(Some("staging"), &args(&["--dart-define=FSP_PROFILE=dev"])).unwrap_err()
        ),
        "`--profile staging` and `--dart-define=FSP_PROFILE=dev` after `--` both name the profile: keep one"
    );
    assert_eq!(
        defined_in(&args(&[
            "--dart-define",
            "FSP_PROFILE=dev",
            "--dart-define=X=1"
        ])),
        Some("dev".to_string())
    );
    assert_eq!(defined_in(&args(&["--dart-define=X=1"])), None);
}

#[test]
fn a_change_in_config_wakes_the_watcher_and_its_other_files_do_not() {
    use notify::event::{CreateKind, DataChange, ModifyKind};
    use notify::{Event, EventKind};
    let root = Path::new("/p");
    let config = root.join("config");
    let app = root.join("lib/app");
    let outputs = vec![
        root.join("lib/app.g.dart"),
        root.join("lib/app.config.g.dart"),
    ];
    let ev = |p: &str| {
        Event::new(EventKind::Modify(ModifyKind::Data(DataChange::Content))).add_path(root.join(p))
    };
    let wakes = |e: &Event| crate::watch::relevant(e, &outputs, &app, &config);
    assert!(wakes(&ev("config/app.yaml")));
    assert!(wakes(&ev("config/app.staging.yaml")));
    assert!(wakes(&ev("config/app.yml")));
    assert!(!wakes(&ev("config/README.md")));
    assert!(!wakes(&ev("config/sub")));
    assert!(wakes(
        &Event::new(EventKind::Create(CreateKind::Folder)).add_path(config.clone())
    ));
    // Writing the generated file does not wake it again.
    assert!(!wakes(&ev("lib/app.config.g.dart")));
    assert!(wakes(&ev("lib/app/page.dart")));
}

/// The dart program that prints what the generated file chose.
const PROBE: &str = "import '../lib/app.config.g.dart';\n\nvoid main() {\n  print('${AppConfig.profile} ${AppConfig.apiBaseUrl} ${AppConfig.newCheckout}');\n  if (AppConfig.newCheckout) print('NEW-CHECKOUT-CODE');\n}\n";

/// `dart` with `args` in `dir`: its stdout, or its stderr when it failed. `None` without dart.
fn dart(dir: &Path, args: &[&str]) -> Option<Result<String, String>> {
    let bin = std::env::var("FSP_DART").unwrap_or_else(|_| "dart".into());
    let out = std::process::Command::new(bin)
        .args(args)
        .current_dir(dir)
        .output()
        .ok()?;
    let text = |b: &[u8]| String::from_utf8_lossy(b).into_owned();
    Some(if out.status.success() {
        Ok(text(&out.stdout))
    } else {
        Err(format!("{}{}", text(&out.stdout), text(&out.stderr)))
    })
}

#[test]
fn the_generated_file_compiles_and_picks_the_profile_the_build_names() {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    write(
        root,
        "pubspec.yaml",
        "name: probe\nenvironment:\n  sdk: ^3.9.0\n",
    );
    write(root, "lib/app.config.g.dart", &generated(&shop()));
    write(root, "bin/main.dart", PROBE);
    let Some(analyzed) = dart(root, &["analyze", "--fatal-infos", "--fatal-warnings"]) else {
        let required = std::env::var("FSP_REQUIRE_DART").is_ok_and(|v| v == "1");
        assert!(
            !required,
            "dart is required (FSP_REQUIRE_DART=1) and is not on PATH"
        );
        return;
    };
    assert!(analyzed.is_ok(), "{analyzed:?}");
    let run = |defines: &[&str]| {
        let mut a = vec!["run"];
        a.extend(defines);
        a.push("bin/main.dart");
        dart(root, &a).unwrap()
    };
    // `dart run` is a debug build: `dev`.
    assert_eq!(
        run(&[]).unwrap(),
        "dev http://localhost:8080 true\nNEW-CHECKOUT-CODE\n"
    );
    assert_eq!(
        run(&["-DFSP_PROFILE=staging"]).unwrap(),
        "staging https://staging.example.com false\n"
    );
    assert_eq!(
        run(&["-DFSP_PROFILE="]).unwrap(),
        "default https://api.example.com false\n"
    );
    assert_eq!(
        run(&["-DFLUTTER_APP_FLAVOR=staging"]).unwrap(),
        "staging https://staging.example.com false\n"
    );
    // A flavour no profile is named after leaves the choice to the build mode.
    assert_eq!(
        run(&["-DFLUTTER_APP_FLAVOR=free"]).unwrap(),
        "dev http://localhost:8080 true\nNEW-CHECKOUT-CODE\n"
    );
    // A release build: `default`.
    assert_eq!(
        run(&["-Ddart.vm.product=true"]).unwrap(),
        "default https://api.example.com false\n"
    );
    // A profile that is not there stops the build, on the line that says why.
    let stopped = run(&["-DFSP_PROFILE=stagng"]).unwrap_err();
    assert!(
        stopped.contains("_fspProfileNamesNoFileOfConfig"),
        "{stopped}"
    );
    // A release build to JavaScript holds its own profile's values and none of the others, nor
    // the code behind a flag that is off.
    let js = root.join("out.js");
    let js_arg = format!("-o{}", js.display());
    let compiled = dart(
        root,
        &[
            "compile",
            "js",
            "-O2",
            "-Ddart.vm.product=true",
            &js_arg,
            "bin/main.dart",
        ],
    )
    .unwrap();
    assert!(compiled.is_ok(), "{compiled:?}");
    let out = fs::read_to_string(&js).unwrap();
    assert!(out.contains("https://api.example.com"));
    for absent in ["localhost:8080", "staging.example.com", "NEW-CHECKOUT-CODE"] {
        assert!(!out.contains(absent), "{absent} is in the release build");
    }
}

#[test]
fn profiles_are_in_the_order_of_their_names() {
    let dir = project(&[
        ("config/app.yaml", "issuer: ''\n"),
        ("config/app.keycloak-dpop.yaml", "issuer: k\n"),
        ("config/app.keycloak.yaml", "issuer: k\n"),
    ]);
    let config = load(dir.path(), "lib/app.config.g.dart").config.unwrap();
    assert_eq!(config.profiles, ["keycloak", "keycloak-dpop"]);
    assert_eq!(
        app_config::profile_names(dir.path()).unwrap(),
        ["keycloak", "keycloak-dpop"]
    );
}

#[test]
fn the_task_commands_get_the_values_of_their_profile() {
    let dir = project(&shop());
    let config = load(dir.path(), "lib/app.config.g.dart").config.unwrap();
    let vars = |name: &str| -> Vec<String> {
        task_vars(&config, name)
            .into_iter()
            .map(|(k, v)| format!("{k}={v}"))
            .collect()
    };
    assert_eq!(
        vars("dev"),
        [
            "FSP_CONFIG_APP_NAME=Shop",
            "FSP_CONFIG_API_BASE_URL=http://localhost:8080",
            "FSP_CONFIG_API_TIMEOUT_MS=8000",
            "FSP_CONFIG_API_RETRY_RATIO=0.5",
            "FSP_CONFIG_NEW_CHECKOUT=true",
            r#"FSP_CONFIG_HOSTS=["localhost","10.0.2.2"]"#,
        ]
    );
    // A null value is no variable; a value no profile changes is app.yaml's.
    assert_eq!(
        vars("staging"),
        [
            "FSP_CONFIG_APP_NAME=Shop",
            "FSP_CONFIG_API_BASE_URL=https://staging.example.com",
            "FSP_CONFIG_API_TIMEOUT_MS=8000",
            "FSP_CONFIG_API_RETRY_RATIO=1.0",
            "FSP_CONFIG_SENTRY_DSN=https://abc@o1.ingest.sentry.io/2",
            "FSP_CONFIG_NEW_CHECKOUT=false",
            r#"FSP_CONFIG_HOSTS=["api.example.com"]"#,
        ]
    );
    assert_eq!(vars("default"), vars("no-such-profile"));
    // Every spelling of a key is one constant and one variable, so two keys that make one
    // variable make one constant, and the constant is said first (see the test of names).
    assert_eq!(
        diags(&[("config/app.yaml", "apiURL: a\napi_url: b\n")]),
        [
            "✗ config/app.yaml:2  `api_url` and `apiURL` would both be the constant AppConfig.apiUrl: rename one"
        ]
    );
}
